const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.file}"/></svg>`;
const btn = (text, action, style='', glyph='') => `<button type="button" class="btn ${style}" data-action="${action}">${glyph ? icon(glyph) : ''}${text}</button>`;
const modes = {public:'Acceso libre',document:'Solo cédula',password:'Cédula y contraseña'};
const kinds = {pdf:'Documento PDF',slides:'Diapositivas',video:'Video',book:'Libro',image:'Imagen',exercise:'Ejercicio',html:'Capítulo HTML',link:'Enlace'};
const kindIcon = kind => ({pdf:'file',slides:'file',video:'video',book:'book',image:'image',exercise:'edit',html:'code',link:'link'}[kind] || 'file');
const badge = mode => `<span class="badge ${mode === 'public' ? 'green' : mode === 'document' ? 'amber' : 'gray'}">${icon(mode === 'public' ? 'globe' : mode === 'document' ? 'users' : 'lock')}${modes[mode]}</span>`;
let state = {user:null,assurance:null,settings:{name:'Aula Abierta',subtitle:'Tu espacio de aprendizaje'},courses:[],students:[],enrollments:[],progress:[],filter:'all',query:'',loginMode:'password',setupRequired:false};
const admin = () => state.user?.role === 'admin';
const student = () => state.user?.role === 'student';
state.learning={courses:[],recent:[],activities:[]};state.resourceFilter='all';
const materialName = kind => !admin()&&kind==='html'?'Lección interactiva':kinds[kind];
const route = () => location.hash.slice(1) || (admin() ? 'inicio' : student() ? 'mis-cursos' : 'catalogo');
const modal = document.getElementById('modal');
const app = document.getElementById('app');
let modalHandler, renderVersion = 0, toastTimer;
async function api(path, options={}) {
  const res = await fetch(`/api${path}`, {credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body === undefined ? undefined : JSON.stringify(options.body)});
  let result; try { result = await res.json(); } catch { throw new Error('No pudimos conectar con el aula. Intenta nuevamente en unos momentos.'); }
  if (!res.ok) throw Object.assign(new Error(result.error || 'No se pudo completar la operación.'),{status:res.status,code:result.code});
  return result.data;
}
const post = (path, body={}) => api(path,{method:'POST',body});
const patch = (path, body) => api(path,{method:'PATCH',body});
function toast(text) { const feedback=modal.open&&modal.querySelector('.viewer-message');if(feedback){feedback.textContent=text;feedback.hidden=false;return;}const t=document.getElementById('toast'); t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4000); }
function date(value) { return value ? new Date(value).toLocaleDateString('es-CO',{day:'2-digit',month:'short',year:'numeric'}) : 'Sin vencimiento'; }
function art() { return '<div class="book-art" aria-hidden="true"><div class="art-circle"></div><div class="art-book back"></div><div class="art-book"></div><span class="spark">✦</span><span class="spark">✧</span></div>'; }
function brand() { return `<a href="#${admin()?'inicio':student()?'mis-cursos':'catalogo'}" class="brand"><span class="brand-mark">${icon('book')}</span>${e(state.settings.name || 'Aula Abierta')}</a>`; }
function heading(title,subtitle,action='') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
function empty(title,copy,action='',glyph='book') { return `<div class="empty"><div class="empty-icon">${icon(glyph)}</div><h3>${title}</h3><p>${copy}</p>${action}</div>`; }
function footer() {return '<footer class="footer"><span>Aula Abierta · Un espacio para compartir conocimiento</span><span>Aprender nos conecta.</span></footer>';}
function shell(content,current) {
  const nav = admin() ? [['inicio','grid','Resumen'],['cursos','book','Mis cursos'],['estudiantes','users','Estudiantes'],['matriculas','cap','Matrículas'],['biblioteca','folder','Biblioteca']] : [['mis-cursos','cap','Mi aprendizaje'],['catalogo','book','Explorar cursos']];
  return `<div class="shell"><aside class="sidebar" id="sidebar">${brand()}<span class="brand-sub">${admin()?'Espacio docente':'Campus virtual'}</span><div class="nav-label">${admin()?'GESTIONAR':'APRENDER'}</div><nav class="nav-list" aria-label="Navegación principal">${nav.map(([id,glyph,text])=>`<a class="nav-link ${current===id?'active':''}" href="#${id}">${icon(glyph)}${text}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="support-card">${icon('help')}<h3>${admin()?'Tu aula, a tu manera':'Aprende a tu ritmo'}</h3><p>${admin()?'Organiza tus materiales y acompaña cada proceso de aprendizaje.':'Tus materiales y actividades, siempre en el mismo lugar.'}</p><button class="text-button" data-action="help">Guía rápida ${icon('arrow')}</button></div><a class="nav-link ${current===(admin()?'ajustes':'cuenta')?'active':''}" href="#${admin()?'ajustes':'cuenta'}">${icon('settings')}${admin()?'Configuración':'Mi cuenta'}</a><div class="profile"><div class="avatar">${e(state.user?.name?.split(' ').map(x=>x[0]).slice(0,2).join('')||'AA')}</div><div class="spacer"><strong>${e(state.user?.name)}</strong><small>${admin()?'Administrador':'Estudiante'}</small></div><button class="icon-btn" data-action="logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><span>${admin()?'Mi espacio docente':'Mi campus'}</span><span>/</span><strong>${e(nav.find(x=>x[0]===current)?.[2] || (current==='ajustes'?'Configuración':current==='cuenta'?'Mi cuenta':'Contenido del curso'))}</strong></div><div class="flex"><span class="status flex"><span class="status-dot"></span>Campus virtual</span>${admin()?'<a href="#catalogo" class="btn secondary small">'+icon('globe')+'Vista del estudiante</a>':''}</div></header><main class="main" id="main">${content}${footer()}</main></div></div>`;
}
function publicShell(content) { return `<header class="public-top flex between">${brand()}<div class="flex"><a href="#catalogo" class="btn ghost small">Cursos</a><a href="#login" class="btn">${icon('logout')}Ingresar al aula</a></div></header><main class="public-main" id="main">${content}${footer()}</main>`; }
function courseCard(c) {if(student())return studentCourseCard(c);const resources=c.modules?.flatMap(m=>m.resources || []) || [];return `<article class="course-card"><div class="course-cover">${safeUrl(c.coverUrl)?`<img src="${e(safeUrl(c.coverUrl))}" alt="" loading="lazy">`:icon('book')}</div><div class="course-body"><div class="flex between">${admin()?badge(c.accessMode):`<span class="badge gray">${c.accessMode==='public'?'Acceso libre':'Curso con matrícula'}</span>`}${admin()?`<span class="badge ${c.published?'green':'gray'}">${c.published?'Publicado':'Borrador'}</span>`:''}</div><h3>${e(c.title)}</h3><p>${e(c.description || 'Un nuevo espacio para aprender.')}</p><div class="course-meta"><span>${icon('folder')}${c.modules?.length ?? c.moduleCount ?? 0} capítulos</span><span>${icon('file')}${c.resourceCount ?? resources.length} recursos</span></div><div class="course-actions"><a class="btn ${admin()?'secondary':''} small" href="#curso/${e(c.id)}">${admin()?'Gestionar curso':c.locked?'Ver acceso':'Entrar al curso'}${icon('arrow')}</a>${admin()?btn('Editar',`edit-course:${c.id}`,'ghost small','edit'):''}</div></div></article>`; }
function dashboard() {
 const allResources=state.courses.flatMap(c=>(c.modules||[]).flatMap(m=>m.resources||[]));
 return heading(`Hola, ${e(state.user.name.split(' ')[0])} <span aria-hidden="true">✺</span>`,'Todo lo que necesitas para dar vida a tus cursos.',btn('Crear curso','new-course','','plus'))+
 `<section class="welcome"><div><div class="overline">EL CONOCIMIENTO EMPIEZA CONTIGO</div><h2>Un lugar para todo lo que enseñas.</h2><p>De la primera diapositiva al último ejercicio. Organiza tus cursos y conecta con tus estudiantes.</p>${btn(state.courses.length?'Gestionar mis cursos':'Crear mi primer curso',state.courses.length?'go:cursos':'new-course','secondary small','arrow')}</div>${art()}</section>`+
 `<div class="stats">${[[state.courses.length,'Cursos creados','book','Tu oferta de aprendizaje'],[state.students.filter(s=>s.active!==false).length,'Estudiantes','users','Personas en tu comunidad'],[state.enrollments.filter(x=>x.active).length,'Matrículas activas','cap','Accesos a tus cursos'],[allResources.length,'Recursos','folder','Materiales para aprender']].map(([n,label,glyph,help])=>`<article class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(glyph)}</span></div><strong>${n}</strong><small>${help}</small></article>`).join('')}</div>`+
 `<div class="dashboard-grid"><section class="panel"><div class="section-head"><h2>Tus cursos</h2><a href="#cursos" class="text-button">Ver todos →</a></div>${state.courses.length?state.courses.slice(0,3).map(c=>`<div class="resource-row"><span class="resource-icon">${icon('book')}</span><div class="spacer"><strong>${e(c.title)}</strong><small>${c.published?'Publicado':'Borrador'} · ${modes[c.accessMode]}</small></div><a class="icon-btn" href="#curso/${c.id}" aria-label="Gestionar ${e(c.title)}">${icon('arrow')}</a></div>`).join(''):empty('Tu próximo curso empieza aquí','Crea un curso, organiza sus capítulos y añade los materiales a tu ritmo.',btn('Crear un curso','new-course','secondary small','plus'))}<div class="resource-types"><span>${icon('file')}Diapositivas</span><span>${icon('video')}Videos</span><span>${icon('book')}Libros</span><span>${icon('edit')}Ejercicios</span></div></section><section class="panel"><div class="section-head"><h2>Prepara tu primera clase</h2>${icon('cap')}</div><p class="small-paragraph">Tres pasos para abrir las puertas de tu aula.</p><div class="steps">${[['Crea tu curso','Define el nombre y el tipo de acceso.'],['Dale forma al contenido','Agrupa tus archivos y enlaces por capítulos.'],['Invita a tus estudiantes','Añádelos por cédula y asígnales su matrícula.']].map(([t,s],i)=>`<div class="step"><span class="step-number">${i+1}</span><div><strong>${t}</strong><p>${s}</p></div></div>`).join('')}</div></section></div>`;
}
function searchBox(placeholder) {return `<div class="search">${icon('search')}<input aria-label="${placeholder}" placeholder="${placeholder}" id="search" value="${e(state.query)}"></div>`;}
function coursesPage(student=false) {
 let list=state.courses.filter(c=>(!student||c.enrolled||c.accessMode==='public') && (state.filter==='all'||state.filter==='published'&&c.published||state.filter==='draft'&&!c.published) && `${c.title} ${c.description}`.toLowerCase().includes(state.query.toLowerCase()));
 return heading(student?'Mi aprendizaje':'Mis cursos',student?'Continúa donde lo dejaste.':'Crea, organiza y comparte tus cursos.',admin()?btn('Crear curso','new-course','','plus'):'')+
 `<div class="toolbar">${searchBox('Buscar un curso…')}${admin()?`<div class="tabs" aria-label="Estado del curso">${[['all','Todos'],['published','Publicados'],['draft','Borradores']].map(([v,t])=>btn(t,`filter:${v}`,`tab ${state.filter===v?'active':''}`)).join('')}</div>`:''}</div>`+
 (list.length?`<div class="course-grid">${list.map(courseCard).join('')}</div>`:empty(state.query?'Sin coincidencias':student?'Tu aprendizaje empieza pronto':'Un aula llena de posibilidades',state.query?'Prueba con otro nombre.':student?'Cuando tu docente te matricule, encontrarás aquí tus cursos.':'Crea tu primer curso. Puedes guardar un borrador y publicarlo cuando esté listo.',admin()?btn('Crear mi primer curso','new-course','','plus'):'','book'));
}
function catalog() {
 const list=state.courses.filter(c=>c.published && `${c.title} ${c.description}`.toLowerCase().includes(state.query.toLowerCase()));
 return (admin()?`<div class="notice">${icon('globe')}Esta es la vista del catálogo. Como administrador puedes abrir también los contenidos restringidos.<a class="text-button" href="#inicio">Volver al panel</a></div>`:'')+
 `<section class="public-banner"><div><span class="overline">BIENVENIDO A TU CAMPUS</span><h1>El siguiente paso<br>en tu aprendizaje.</h1><p>${e(state.settings.subtitle || 'Explora tus cursos, encuentra tus materiales y aprende a tu ritmo.')}</p></div>${art()}</section><div class="section-head"><div><h2>Explora los cursos</h2><small>Un espacio para aprender y seguir creciendo</small></div></div><div class="toolbar">${searchBox('Buscar en el catálogo…')}<span class="muted">${list.length} cursos disponibles</span></div>`+
 (list.length?`<div class="course-grid">${list.map(courseCard).join('')}</div>`:empty('Estamos preparando tu próxima clase','Los cursos publicados aparecerán aquí. Si ya estás matriculado, ingresa con tu cédula.',state.user?'':'<a class="btn secondary" href="#login">Ingresar al aula →</a>'));
}
function studentsPage() {
 const list=state.students.filter(s=>`${s.document} ${s.name} ${s.email}`.toLowerCase().includes(state.query.toLowerCase()));
 return heading('Estudiantes','Las personas que forman parte de tu aula.',`<div class="flex wrap">${btn('Importar lista','import-students','secondary','upload')}${btn('Añadir estudiante','new-student','','plus')}</div>`)+
 `<div class="toolbar">${searchBox('Buscar por nombre o cédula…')}<small class="muted">${state.students.length} estudiantes registrados</small></div>`+
 (list.length?`<div class="panel table-panel table-wrap"><table><thead><tr><th>ESTUDIANTE</th><th>CÉDULA</th><th>ESTADO</th><th>GESTIONAR</th></tr></thead><tbody>${list.map(s=>`<tr><td><strong>${e(s.name)}</strong><span class="muted">${e(s.email||'Sin correo registrado')}</span></td><td>${e(s.document)}</td><td><span class="badge ${s.active?'green':'gray'}">${s.active?'Activo':'Suspendido'}</span></td><td class="actions">${btn('Editar',`edit-student:${s.id}`,'ghost small','edit')}${btn('Código',`activate-student:${s.id}`,'ghost small','lock')}</td></tr>`).join('')}</tbody></table></div>`:empty('Conoce a tu comunidad','Añade estudiantes uno a uno o importa una lista CSV. Su cédula será su nombre de usuario.',btn('Añadir estudiante','new-student','','plus'),'users'));
}
function enrollmentsPage() {
 return heading('Matrículas','Decide quién puede acceder a cada curso y durante cuánto tiempo.',btn('Nueva matrícula','new-enrollment','','plus'))+
 (state.enrollments.length?`<div class="panel table-panel table-wrap"><table><thead><tr><th>ESTUDIANTE</th><th>CURSO</th><th>VIGENCIA</th><th>ESTADO</th><th></th></tr></thead><tbody>${state.enrollments.map(x=>{const s=state.students.find(y=>y.id===x.studentId),c=state.courses.find(y=>y.id===x.courseId);const expired=x.expiresAt&&new Date(x.expiresAt)<new Date();return `<tr><td><strong>${e(s?.name||x.studentName||'Estudiante')}</strong><span class="muted">${e(s?.document||'')}</span></td><td>${e(c?.title||x.courseTitle||'Curso')}</td><td>${date(x.expiresAt)}<span class="muted">${x.startsAt?'Desde '+date(x.startsAt):'Acceso inmediato'}</span></td><td><span class="badge ${x.status==='active'&&!expired?'green':'gray'}">${x.status==='revoked'?'Revocada':expired?'Vencida':x.startsAt&&new Date(x.startsAt)>new Date()?'Programada':'Activa'}</span></td><td class="actions">${btn('Editar',`edit-enrollment:${x.id}`,'ghost small','edit')}${btn(x.status==='active'?'Revocar':'Reactivar',`toggle-enrollment:${x.id}`,'ghost small')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Abre las puertas a tus estudiantes','Primero crea un curso y registra estudiantes. Luego asígnales una matrícula.',btn('Crear una matrícula','new-enrollment','','plus'),'cap'));
}
function libraryPage() {
 const resources=state.courses.flatMap(c=>(c.modules||[]).flatMap(m=>(m.resources||[]).map(r=>({...r,courseTitle:c.title,courseId:c.id,moduleTitle:m.title})))).filter(r=>`${r.title} ${r.courseTitle}`.toLowerCase().includes(state.query.toLowerCase()));
 return heading('Biblioteca','Todos tus materiales, organizados por curso.',btn('Añadir material','library-add','','plus'))+`<div class="toolbar">${searchBox('Buscar un material…')}<small class="muted">${resources.length} recursos</small></div>`+
 (resources.length?`<div class="library-list">${resources.map(r=>`<div class="resource-row"><span class="resource-icon">${icon(kindIcon(r.kind))}</span><div class="spacer"><strong>${e(r.title)}</strong><small>${e(r.courseTitle)} · ${e(r.moduleTitle)}</small></div><span class="badge gray">${kinds[r.kind]}</span>${btn('Abrir',`resource:${r.id}`,'secondary small','arrow')}</div>`).join('')}</div>`:empty('Tu biblioteca está lista para crecer','Añade diapositivas, libros, imágenes y ejercicios dentro de cada capítulo. También puedes enlazar videos.',btn('Ir a mis cursos','go:cursos','secondary','book'),'folder'));
}
function settingsPage() {return heading('Configuración','Haz que este espacio se sienta como tu aula.')+`<div class="settings-grid"><section class="panel"><h2>Identidad del campus</h2><form id="settings-form" class="form-stack"><label>Nombre de la plataforma<input name="name" required maxlength="80" value="${e(state.settings.name)}"></label><label>Descripción de bienvenida<textarea name="subtitle" maxlength="240">${e(state.settings.subtitle)}</textarea></label><label>Correo de contacto<input type="email" name="contactEmail" value="${e(state.settings.contactEmail||'')}"></label><div class="form-error" role="alert"></div><button class="btn" type="submit">Guardar cambios</button></form></section><section class="panel"><h2>Acceso a los cursos</h2>${Object.entries(modes).map(([k,t])=>`<div class="mode-card">${badge(k)}<p>${{public:'Cualquier persona puede ver el curso publicado, sin iniciar sesión.',document:'Solo estudiantes matriculados. La cédula identifica al estudiante, pero no comprueba su identidad.',password:'Estudiantes matriculados que hayan iniciado sesión con su cédula y contraseña.'}[k]}</p></div>`).join('')}<div class="form-actions">${btn('Cambiar mi contraseña','change-password','secondary','lock')}</div></section></div>`;}
function loginPage() {return `<div class="login-layout"><div class="login-side"><div><span class="overline">TU ESPACIO DE APRENDIZAJE</span><h1 style="margin-top:20px">Cada gran idea<br>empieza en un aula.</h1><p>Tus cursos, tus materiales y todo lo que necesitas para seguir aprendiendo.</p></div>${art()}<small>Aula Abierta · Campus virtual</small></div><section class="login-form"><h2>${state.loginMode==='activate'?'Crea o recupera tu contraseña':'Qué bueno verte'}</h2><p>${state.loginMode==='activate'?'Usa el código que te entregó tu docente.':'Ingresa para continuar con tus cursos.'}</p>${state.setupRequired?'<div class="notice">El aula se está preparando. Tu docente te avisará cuando puedas ingresar.</div>':''}<div class="login-tabs">${[['password','Con contraseña'],['document','Solo cédula']].map(([m,t])=>`<button class="tab ${state.loginMode===m?'active':''}" data-action="login-mode:${m}">${t}</button>`).join('')}</div><form id="login-form" class="form-stack"><label>Cédula<input name="document" inputmode="numeric" autocomplete="username" pattern="[0-9]{4,20}" required placeholder="Tu número de cédula"><span class="field-hint">Escríbela sin puntos ni espacios.</span></label>${state.loginMode==='activate'?'<label>Código de activación<input name="code" required autocomplete="off" placeholder="Código entregado por tu docente"></label>':''}${state.loginMode!=='document'?`<label>${state.loginMode==='activate'?'Crea tu contraseña':'Contraseña'}<input name="password" type="password" autocomplete="${state.loginMode==='activate'?'new-password':'current-password'}" required ${state.loginMode==='activate'?'minlength="12"':''} placeholder="${state.loginMode==='activate'?'Mínimo 12 caracteres':'Tu contraseña'}"></label>`:'<p class="field-hint">Usa esta opción si tu docente te indicó ingresar sin contraseña.</p>'}<div class="form-error" role="alert"></div><button type="submit" class="btn">${state.loginMode==='activate'?'Crear contraseña e ingresar':'Ingresar a mi aula'}${icon('arrow')}</button></form><p style="margin-top:22px;font-size:.8rem"><button class="text-button" data-action="login-mode:${state.loginMode==='activate'?'password':'activate'}">${state.loginMode==='activate'?'Ya tengo contraseña':'Primera vez o recuperación de acceso'}</button></p><p class="field-hint" style="margin-top:14px">Si necesitas recuperar el acceso, solicita un código nuevo a tu docente.${state.settings.contactEmail?' Contacto: '+e(state.settings.contactEmail):''}</p></section></div>`;}

function studyButton(courseId,resourceId,label='Continuar curso',style='') {
 return btn(label,`study:${courseId}/${resourceId}`,style,'arrow');
}
function progressBar(percent,label) {return `<div class="progress-track" role="progressbar" aria-label="${e(label)}" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${percent}%"></div></div>`;}
function contactTeacher() {return state.settings.contactEmail?`<a class="text-button" href="mailto:${e(state.settings.contactEmail)}">${icon('mail')} Contactar a mi docente</a>`:'Si necesitas ayuda con un curso, comunícate con tu docente.';}
function studentCourseCard(c) {
 const learning=state.learning.courses.find(x=>x.courseId===c.id),total=learning?.total??c.resourceCount??0,done=learning?.completed||0,percent=total?Math.round(done/total*100):0;
 return `<article class="course-card learning-course-card"><div class="course-cover">${safeUrl(c.coverUrl)?`<img src="${e(safeUrl(c.coverUrl))}" alt="" loading="lazy">`:icon('book')}</div><div class="course-body"><span class="badge ${c.locked?'gray':'green'}">${c.locked?'Acceso requerido':c.enrolled?'Matriculado':'Curso abierto'}</span><h3>${e(c.title)}</h3><p>${e(c.description||'Tus materiales y actividades en un solo lugar.')}</p><div class="course-meta"><span>${icon('folder')}${c.moduleCount||0} capítulos</span><span>${icon('file')}${total} materiales</span></div>${!c.locked&&total?`<div class="learning-card-progress"><div class="flex between"><strong>${percent}% completado</strong><small>${done} de ${total}</small></div>${progressBar(percent,`Avance en ${c.title}`)}<small>${total-(learning?.opened||0)} sin abrir · ${Math.max(0,total-done)} pendientes</small></div>`:!c.locked?'<p class="field-hint">Tu docente está preparando los materiales.</p>':''}<div class="course-actions">${learning?.nextResource?studyButton(c.id,learning.nextResource.id,learning.opened?'Continuar curso':'Comenzar curso','small'):`<a class="btn small" href="#curso/${e(c.id)}">${c.locked?'Ver acceso':total&&done===total?'Repasar curso':'Entrar al curso'}${icon('arrow')}</a>`}</div></div></article>`;
}
function learningPage() {
 const courses=state.courses.filter(c=>c.enrolled||c.accessMode==='public'),list=courses.filter(c=>`${c.title} ${c.description}`.toLowerCase().includes(state.query.toLowerCase()));
 const summaries=state.learning.courses,totals=summaries.reduce((a,c)=>({completed:a.completed+c.completed,unopened:a.unopened+c.total-c.opened,activities:a.activities+c.exercisesTotal-c.exercisesCompleted}),{completed:0,unopened:0,activities:0});
 const recent=state.learning.recent||[],activities=state.learning.activities||[];
 const learningList=(items,activity=false)=>items.length?`<div class="learning-list">${items.map(x=>`<div class="resource-row"><span class="resource-icon">${icon(kindIcon(x.kind))}</span><div class="spacer"><strong>${e(x.title)}</strong><small>${e(x.courseTitle)}${!activity&&x.lastOpenedAt?' · '+date(x.lastOpenedAt):''}</small></div>${studyButton(x.courseId,x.resourceId,activity?'Abrir':'Retomar','secondary small')}</div>`).join('')}</div>`:`<p class="small-paragraph">${activity?'No tienes actividades pendientes en tus cursos disponibles.':'Aquí aparecerán los materiales que vayas abriendo.'}</p>`;
 return heading(`Hola, ${e(state.user.name.split(' ')[0])}`,'Este es tu espacio para continuar, revisar pendientes y ver tu avance.')+
 `<div class="stats learning-stats">${[[summaries.length,'Cursos disponibles','book'],[totals.completed,'Materiales completados','check'],[totals.unopened,'Materiales sin abrir','file'],[totals.activities,'Actividades pendientes','edit']].map(([n,label,glyph])=>`<article class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(glyph)}</span></div><strong>${n}</strong></article>`).join('')}</div>`+
 `<div class="learning-overview"><section class="panel"><div class="section-head"><h2>Retoma tus materiales</h2>${icon('clock')}</div>${learningList(recent)}</section><section class="panel"><div class="section-head"><h2>Actividades pendientes</h2>${icon('edit')}</div>${learningList(activities,true)}</section></div>`+
 `<div class="section-head"><h2>Mis cursos</h2><a class="text-button" href="#catalogo">Explorar cursos →</a></div><div class="toolbar">${searchBox('Buscar entre mis cursos…')}</div>`+
 (list.length?`<div class="course-grid">${list.map(studentCourseCard).join('')}</div>`:empty(state.query?'Sin coincidencias':'Tu aprendizaje empieza pronto',state.query?'Prueba con otro nombre.':'Cuando tu docente te matricule, encontrarás aquí tus cursos. También puedes explorar los cursos abiertos.','<a class="btn secondary" href="#catalogo">Explorar cursos</a>'));
}
function learnerCoursePage(c) {
 const resources=c.modules.flatMap(m=>m.resources||[]),summary=summarizeLearning(resources,state.progress),labels={completed:'Completado',opened:'Abierto',unopened:'Sin abrir'};
 const filters=student()?[['all','Todos',summary.total],['pending','Pendientes',summary.pending],['unopened','Sin abrir',summary.unopened],['activities','Actividades',summary.exercisesTotal]]:[['all','Todos',summary.total],['activities','Actividades',summary.exercisesTotal]];
 const accepts=r=>state.resourceFilter==='pending'?materialStatus(r.id,state.progress)!=='completed':state.resourceFilter==='unopened'?materialStatus(r.id,state.progress)==='unopened':state.resourceFilter==='activities'?r.kind==='exercise':true;
 const modules=c.modules.map(m=>({...m,visible:m.resources.filter(accepts)}));
 const resourceRow=r=>{const status=materialStatus(r.id,state.progress);return `<div class="resource-row learning-resource ${student()?status:''}"><span class="resource-icon">${icon(status==='completed'&&student()?'check':kindIcon(r.kind))}</span><div class="spacer"><strong>${e(r.title)}</strong><small>${materialName(r.kind)}</small></div>${student()?`<span class="badge ${status==='completed'?'green':status==='opened'?'amber':'gray'}">${labels[status]}</span>`:''}<button type="button" class="btn secondary small" data-action="resource:${r.id}" aria-label="Abrir ${e(r.title)}">Abrir ${icon('arrow')}</button></div>`;};
 const activities=resources.filter(r=>r.kind==='exercise'&&materialStatus(r.id,state.progress)!=='completed');
 return `<a class="text-button" href="#${student()?'mis-cursos':'catalogo'}">← ${student()?'Volver a mi aprendizaje':'Volver a los cursos'}</a><div class="course-header learner-course-header"><div><span class="overline">${c.enrolled?'MI CURSO':'ESPACIO DE APRENDIZAJE'}</span><h1>${e(c.title)}</h1>${c.description?`<p>${e(c.description)}</p>`:''}</div></div>`+
 (student()?`<section class="learning-course-summary"><div class="learning-ring" style="--progress:${summary.percent}%" role="img" aria-label="${summary.percent}% del curso completado"><div><strong>${summary.percent}%</strong><span>completado</span></div></div><div class="learning-summary-body"><h2>${summary.total&&summary.completed===summary.total?'Completaste todos los materiales':summary.opened?'Sigue avanzando a tu ritmo':'Tu siguiente paso empieza aquí'}</h2><p>${summary.completed} de ${summary.total} materiales completados</p><div class="learning-counts"><span><strong>${summary.unopened}</strong> sin abrir</span><span><strong>${summary.inProgress}</strong> abiertos por terminar</span><span><strong>${summary.exercisesTotal-summary.exercisesCompleted}</strong> actividades pendientes</span></div></div>${summary.next?`<div class="learning-next"><small>SIGUIENTE MATERIAL</small><strong>${e(summary.next.title)}</strong>${btn(summary.opened?'Continuar curso':'Comenzar curso',`resource:${summary.next.id}`,'','arrow')}</div>`:''}</section>`:'')+
 `<div class="detail-grid learner-detail"><section><div class="section-head"><h2>Contenido del curso</h2><small>${c.modules.length} capítulos · ${summary.total} materiales</small></div><div class="learning-filters" aria-label="Filtrar materiales">${filters.map(([value,label,count])=>`<button type="button" class="learning-filter" data-action="resource-filter:${value}" aria-pressed="${state.resourceFilter===value}">${label}<span>${count}</span></button>`).join('')}</div>`+
 ((resources.length||state.resourceFilter!=='all')&&!modules.some(m=>m.visible.length)?empty('No hay materiales en esta vista','Puedes elegir otro filtro para seguir explorando el curso.',btn('Ver todos','resource-filter:all','secondary')):modules.length?modules.filter(m=>m.visible.length||state.resourceFilter==='all').map(m=>{const s=summarizeLearning(m.resources,state.progress);return `<article class="module"><div class="module-head"><div class="module-title"><span class="number">${String(c.modules.findIndex(x=>x.id===m.id)+1).padStart(2,'0')}</span><h3>${e(m.title)}</h3></div>${student()?`<span class="module-progress">${s.completed}/${s.total} completados</span>`:''}</div>${student()&&s.total?progressBar(s.percent,`Avance en ${m.title}`):''}${m.visible.length?m.visible.map(resourceRow).join(''):'<p class="small-paragraph" style="padding:24px">Tu docente está preparando los materiales de este capítulo.</p>'}</article>`;}).join(''):empty('El contenido estará disponible pronto','Tu docente está preparando los materiales de este curso.','','book'))+
 `</section><aside class="learner-course-aside"><section class="panel"><h2>${student()?'Tus actividades':'Aprende a tu ritmo'}</h2>${student()?`<p class="small-paragraph">${activities.length?`${activities.length} actividades por completar`:'No tienes actividades pendientes.'}</p>${activities.slice(0,3).map(r=>`<div class="learning-activity"><strong>${e(r.title)}</strong>${btn('Abrir actividad',`resource:${r.id}`,'secondary small','edit')}</div>`).join('')}`:'<p class="small-paragraph">Ingresa para guardar tu avance y retomar tus materiales desde cualquier dispositivo.</p><a class="btn secondary" href="#login">Ingresar al aula</a>'}</section><section class="panel learning-help">${student()?'<h2>Tu avance, a tu ritmo</h2><p class="small-paragraph">Abrir un material lo marca como abierto. Cuando termines de estudiarlo, pulsa <strong>Marcar completado</strong>. Puedes volver a dejarlo pendiente.</p><p class="field-hint">El porcentaje representa materiales completados, no una calificación.</p>':'<h2>Para aprovechar el curso</h2><p class="small-paragraph">Explora los capítulos y abre sus materiales. Ingresa al aula para guardar tu avance y marcar lo que ya completaste.</p>'}<div class="learning-contact">${contactTeacher()}</div></section></aside></div>`;
}

async function coursePage(id,version) {
 state.currentCourse=null;
 let c;try {c=await api(`/courses/${id}`);}catch(error){
  const known=state.courses.find(course=>course.id===id),needsLogin=!state.user||error.status===401,passwordNeeded=state.user&&state.assurance!=='password'&&known?.accessMode==='password';
  if(error.status===404)return heading('Curso no disponible','Este curso no está disponible en este momento.')+'<a class="btn secondary" href="#mis-cursos">Volver a mi aprendizaje</a>';
  if(![401,403].includes(error.status))return heading('No pudimos cargar el curso','Intenta nuevamente en unos momentos.')+btn('Volver a intentar','reload','secondary','arrow');
  const message=needsLogin?'Ingresa para consultar los materiales de este curso.':passwordNeeded?'Este curso requiere que ingreses con tu contraseña.':'No tienes una matrícula vigente en este curso. Consulta con tu docente.';
  return heading('Acceso al curso',message)+(needsLogin||passwordNeeded?btn('Ingresar al aula','course-login:'+id,'','lock'):`<section class="panel"><p class="small-paragraph">${contactTeacher()}</p><div class="form-actions"><a class="btn secondary" href="#mis-cursos">Volver a mi aprendizaje</a></div></section>`);
 }
 if(version!==renderVersion)return '';
 state.currentCourse=c;
 if(!admin())return learnerCoursePage(c);
 const resources=(c.modules||[]).flatMap(m=>m.resources||[]),done=resources.filter(r=>state.progress.some(p=>p.resourceId===r.id&&p.completed)).length;
 return `<a class="text-button" href="#${admin()?'cursos':'catalogo'}">← Volver a los cursos</a><div class="course-header"><div><div style="margin-top:24px" class="flex">${badge(c.accessMode)}${!c.published?'<span class="badge gray">Borrador</span>':''}</div><h1>${e(c.title)}</h1><p>${e(c.description)}</p></div>${admin()?`<div class="flex wrap" style="margin-top:26px">${btn('Editar curso',`edit-course:${c.id}`,'secondary','edit')}${btn(c.published?'Volver a borrador':'Publicar curso',`publish-course:${c.id}`,'','globe')}</div>`:''}</div>${c.accessMode==='document'?'<div class="notice warning">'+icon('shield')+'Este curso permite entrar con solo cédula. Este método no comprueba la identidad de quien accede.</div>':''}<div class="detail-grid"><section><div class="section-head"><h2>Contenido del curso</h2>${admin()?btn('Añadir capítulo',`new-module:${c.id}`,'secondary small','plus'):`<small>${c.modules.length} capítulos · ${resources.length} recursos</small>`}</div>${c.modules.length?c.modules.map((m,i)=>`<article class="module"><div class="module-head"><div class="module-title"><span class="number">${String(i+1).padStart(2,'0')}</span><h3>${e(m.title)}</h3></div>${admin()?`<div class="flex">${btn('Material',`new-resource:${m.id}`,'ghost small','plus')}<button class="icon-btn" data-action="edit-module:${m.id}" aria-label="Editar capítulo">${icon('edit')}</button><button class="icon-btn" data-action="delete-module:${m.id}" aria-label="Eliminar capítulo">${icon('trash')}</button></div>`:''}</div>${m.resources.length?m.resources.map(r=>`<div class="resource-row"><span class="resource-icon">${icon(kindIcon(r.kind))}</span><div class="spacer"><strong>${e(r.title)}</strong><small>${kinds[r.kind]}${state.progress.some(p=>p.resourceId===r.id&&p.completed)?' · Completado':''}</small></div>${btn('Abrir',`resource:${r.id}`,'secondary small','arrow')}${admin()?`<button class="icon-btn" data-action="edit-resource:${r.id}" aria-label="Editar recurso">${icon('edit')}</button><button class="icon-btn" data-action="delete-resource:${r.id}" aria-label="Eliminar recurso">${icon('trash')}</button>`:''}</div>`).join(''):`<p class="small-paragraph" style="padding:24px">${admin()?'Añade el primer material de este capítulo.':'Tu docente está preparando los materiales.'}</p>`}</article>`).join(''):empty('Empieza por el primer capítulo',admin()?'Divide el curso en capítulos y añade sus materiales.':'El contenido de este curso estará disponible pronto.',admin()?btn('Crear capítulo',`new-module:${c.id}`,'secondary','plus'):'','folder')}</section><aside><div class="panel"><h2>${admin()?'Tu curso, paso a paso':'Tu avance'}</h2>${admin()?`<div class="steps"><div class="step">${icon('folder')}<span class="small-paragraph">${c.modules.length} capítulos organizados</span></div><div class="step">${icon('file')}<span class="small-paragraph">${resources.length} materiales añadidos</span></div><div class="step">${icon('users')}<span class="small-paragraph">${state.enrollments.filter(x=>x.courseId===c.id&&x.active).length} matrículas activas</span></div></div><div class="form-actions">${btn('Matricular estudiantes',`enroll-course:${c.id}`,'secondary small')}</div>`:`<div class="progress-track"><div class="progress-fill" style="width:${resources.length?Math.round(done/resources.length*100):0}%"></div></div><p class="small-paragraph">${done} de ${resources.length} recursos completados</p>${!state.user?'<p class="field-hint" style="margin-top:12px">Ingresa para guardar tu avance.</p>':''}`}<div class="mode-card" style="margin-top:18px"><p>Abre cada recurso para leerlo, verlo o descargarlo.</p></div>${admin()?btn('Eliminar curso',`delete-course:${c.id}`,'danger small','trash'):''}</div></aside></div>`;
}
async function refresh() {
 const isAdmin=admin();
 const results=await Promise.all([api(isAdmin?'/admin/courses':'/courses'),isAdmin?api('/admin/students'):Promise.resolve([]),isAdmin?api('/admin/enrollments'):Promise.resolve([]),state.user?api('/progress'):Promise.resolve([]),student()?api('/learning'):Promise.resolve({courses:[],recent:[],activities:[]})]);
 [state.courses,state.students,state.enrollments,state.progress,state.learning]=results;
}
async function render() {
 const version=++renderVersion; const current=route();let content;
 try {
  if(current==='login') content=loginPage();
  else if(current.startsWith('curso/')) content=await coursePage(current.slice(6),version);
  else if(current==='catalogo') content=catalog();
  else if(!state.user){location.hash='login';return;}
  else if(current==='mis-cursos') content=admin()?coursesPage(true):learningPage();
  else if(current==='cuenta') content=heading('Mi cuenta','Tu información de acceso.')+`<section class="panel" style="max-width:650px"><h2>${e(state.user.name)}</h2><p class="small-paragraph" style="margin:15px 0">Usuario: ${e(state.user.document)}<br>Acceso actual: ${state.assurance==='password'?'Con contraseña':'Solo cédula'}</p>${state.assurance==='password'?btn('Cambiar contraseña','change-password','secondary','lock'):btn('Ingresar con contraseña','password-login','secondary','lock')}</section>`;
  else if(!admin()){location.hash='mis-cursos';return;}
  else content=({inicio:dashboard,cursos:()=>coursesPage(),estudiantes:studentsPage,matriculas:enrollmentsPage,biblioteca:libraryPage,ajustes:settingsPage}[current]||dashboard)();
  if(version!==renderVersion)return;
  app.innerHTML=state.user&&current!=='login'?shell(content,current):publicShell(content);
  if(admin()&&current==='ajustes')document.querySelector('.settings-grid')?.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Trasladar un aula existente</h2><p class="small-paragraph">Importa una copia de migración en una plataforma sin cursos ni estudiantes. Conserva la cuenta de administrador de destino. El archivo contiene datos privados: no lo subas a GitHub.</p><div class="form-actions">${btn('Importar traslado','import-migration','secondary','upload')}</div></section>`);
  bindForms();
  if(state.pendingResourceId&&current.startsWith('curso/')){const resourceId=state.pendingResourceId;state.pendingResourceId=null;if(state.currentCourse?.modules.some(m=>m.resources.some(r=>r.id===resourceId)))await viewResource(resourceId);}
 }catch(error){app.innerHTML=publicShell(`<div class="notice error">${e(error.message)}</div>${btn('Volver a intentar','reload','','arrow')}`);}
}
function openModal(title,body,onSubmit,{wide=false,submit='Guardar'}={}) {
 if(modal.open)modal.close();
 document.documentElement.classList.remove('resource-viewer-open');
 modal.className=wide?'wide':'';
 modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div>${onSubmit?'<form id="modal-form">':''}${body}${onSubmit?`<div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancelar</button><button type="submit" class="btn">${submit}</button></div></form>`:''}`;
 modalHandler=onSubmit;modal.showModal();
}
function openResourceViewer(resource,view,actions) {
 if(modal.open)modal.close();
 modal.className='resource-viewer';
 modal.innerHTML=`<header class="viewer-header"><button type="button" class="btn secondary viewer-back" data-action="close-modal" aria-label="Volver al curso" autofocus>${icon('arrow')}<span class="viewer-action-label">Volver al curso</span></button><div class="viewer-heading"><h2 id="modal-title" title="${e(resource.title)}">${e(resource.title)}</h2><span>${materialName(resource.kind)}</span></div><div class="viewer-actions">${actions}<button type="button" class="icon-btn" data-action="close-modal" aria-label="Cerrar material" title="Cerrar material">${icon('close')}</button></div></header><p class="viewer-message" role="status" hidden></p><div class="content-view">${view}</div>`;
 modalHandler=null;state.activeResourceId=resource.id;state.activeResourceRoute=route();
 document.documentElement.classList.add('resource-viewer-open');
 modal.showModal();
}
async function submitForm(form,fn) {
 const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');error.textContent='';submit.disabled=true;
 try {await fn(new FormData(form));}catch(err){error.textContent=err.message;}finally{submit.disabled=false;}
}
function values(fd){return Object.fromEntries(fd.entries());}
function findCourse(id){return state.courses.find(c=>c.id===id)||state.currentCourse;}
function allModules(){return state.courses.flatMap(c=>c.modules||[]).concat(state.currentCourse?.modules||[]);}
function findResource(id){return allModules().flatMap(m=>m.resources||[]).find(r=>r.id===id);}
async function saved(message='Cambios guardados') {modal.close();await refresh();await render();toast(message);}
function courseForm(id) {
 const c=id?findCourse(id):{title:'',description:'',accessMode:'password',published:false};
 openModal(id?'Editar curso':'Un nuevo espacio para aprender',`<div class="form-stack"><label>Nombre del curso<input name="title" required maxlength="180" placeholder="¿Qué vas a enseñar?" value="${e(c.title)}"></label><label>Descripción<textarea name="description" maxlength="4000" placeholder="Cuenta a tus estudiantes qué encontrarán aquí.">${e(c.description)}</textarea></label><label>¿Cómo se ingresa a este curso?<select name="accessMode">${Object.entries(modes).map(([k,t])=>`<option value="${k}" ${c.accessMode===k?'selected':''}>${t}</option>`).join('')}</select><span class="field-hint">Los cursos restringidos requieren una matrícula. Solo cédula ofrece una verificación básica, sin comprobar la identidad.</span></label><label>Imagen de portada (opcional)<input type="url" name="coverUrl" placeholder="https://…" value="${e(c.coverUrl||'')}"></label><label class="check-label"><input type="checkbox" name="published" ${c.published?'checked':''}>Publicar en el catálogo</label><span class="field-hint">Sin publicar, solo tú puedes ver el contenido.</span></div>`,async fd=>{const data={...values(fd),published:fd.has('published')};await (id?patch(`/admin/courses/${id}`,data):post('/admin/courses',data));await saved(id?'Curso actualizado':'Tu curso está creado');});
}
function studentForm(id) {
 const s=id?state.students.find(x=>x.id===id):{};
 openModal(id?'Editar estudiante':'Añadir estudiante',`<div class="form-stack"><label>Nombre completo<input name="name" required maxlength="160" value="${e(s.name||'')}"></label><label>Cédula<input name="document" inputmode="numeric" pattern="[0-9]{4,20}" required ${id?'readonly':''} value="${e(s.document||'')}"><span class="field-hint">Será el usuario para ingresar. Sin puntos ni espacios.</span></label><label>Correo (opcional)<input name="email" type="email" value="${e(s.email||'')}"></label>${id?`<label class="check-label"><input type="checkbox" name="active" ${s.active?'checked':''}>Cuenta activa</label>`:'<div class="notice">Al guardar se generará un código privado para que el estudiante cree su contraseña.</div>'}</div>`,async fd=>{const data=values(fd);if(id)data.active=fd.has('active');const result=await(id?patch(`/admin/students/${id}`,data):post('/admin/students',data));await saved(id?'Estudiante actualizado':'Estudiante registrado');if(result.activationCode)showCode(result.activationCode,data.name);});
}
function showCode(code,name) {openModal('Código de activación',`<p class="small-paragraph">Entrega este código de forma privada a <strong>${e(name)}</strong>. Le permitirá crear o restablecer su contraseña desde “Primera vez o recuperación de acceso”.</p><div class="code-box"><code>${e(code)}</code></div><p class="field-hint">Se muestra una sola vez. Al usarse queda invalidado. Puedes generar otro desde Estudiantes.</p><div class="form-actions">${btn('Listo','close-modal')}</div>`);}
function enrollmentForm(id,courseId) {
 if(!state.students.length||!state.courses.length){openModal('Primero prepara tu aula','<p class="small-paragraph">Necesitas al menos un estudiante y un curso para crear una matrícula.</p><div class="form-actions">'+btn('Entendido','close-modal')+'</div>');return;}
 const x=id?state.enrollments.find(y=>y.id===id):{courseId};
 openModal(id?'Editar matrícula':'Nueva matrícula',`<div class="form-stack"><label>Estudiante<select name="studentId" ${id?'disabled':''}>${state.students.map(s=>`<option value="${s.id}" ${s.id===x.studentId?'selected':''}>${e(s.name)} · ${e(s.document)}</option>`).join('')}</select></label><label>Curso<select name="courseId" ${id?'disabled':''}>${state.courses.map(c=>`<option value="${c.id}" ${c.id===x.courseId?'selected':''}>${e(c.title)}</option>`).join('')}</select></label><div class="form-grid"><label>Inicio (opcional)<input type="date" name="startsAt" value="${x.startsAt?.slice(0,10)||''}"></label><label>Último día de acceso<input type="date" name="expiresAt" value="${x.expiresAt?.slice(0,10)||''}"></label></div><span class="field-hint">Sin fechas, el acceso comienza ahora y no vence. Las fechas usan el horario del servidor (UTC).</span></div>`,async fd=>{const data=values(fd);data.startsAt=data.startsAt?`${data.startsAt}T00:00:00.000Z`:null;data.expiresAt=data.expiresAt?`${data.expiresAt}T23:59:59.999Z`:null;await(id?patch(`/admin/enrollments/${id}`,data):post('/admin/enrollments',data));await saved('Matrícula guardada');});
}
function moduleForm(id,courseId) {
 const m=id?allModules().find(x=>x.id===id):{title:'',position:state.currentCourse?.modules.length||0};
 openModal(id?'Editar capítulo':'Añadir capítulo',`<div class="form-stack"><label>Título del capítulo<input name="title" required maxlength="180" placeholder="Nombre del capítulo" value="${e(m.title)}"></label><label>Orden<input name="position" type="number" min="0" max="10000" value="${m.position||0}"></label></div>`,async fd=>{const data={...values(fd),position:Number(fd.get('position'))};await(id?patch(`/admin/modules/${id}`,data):post(`/admin/courses/${courseId}/modules`,data));await saved('Capítulo guardado');});
}
function resourceForm(id,moduleId) {
 const r=id?findResource(id):{title:'',kind:'pdf',position:0};
 openModal(id?'Editar material':'Añadir material',`<div class="form-stack"><div class="form-grid"><label class="full">Título<input name="title" required maxlength="180" value="${e(r.title)}" placeholder="Nombre del material"></label><label>Tipo de recurso<select name="kind">${Object.entries(kinds).map(([k,t])=>`<option value="${k}" ${r.kind===k?'selected':''}>${t}</option>`).join('')}</select></label><label>Orden<input type="number" name="position" min="0" max="10000" value="${r.position||0}"></label></div><label>Subir archivo (opcional)<input type="file" name="file" accept=".pdf,.pptx,.docx,.png,.jpg,.jpeg,.webp,.gif,.html,.txt"><span class="field-hint">Máximo 20 MB. PDF e imágenes tienen vista previa; PowerPoint y Word se descargan.${r.fileName?' Archivo actual: '+e(r.fileName):''}</span></label>${r.fileName?'<label class="check-label"><input name="removeFile" type="checkbox">Quitar archivo actual</label>':''}<label>Enlace a video o material (opcional)<input type="url" name="url" placeholder="https://…" value="${e(r.url||'')}"><span class="field-hint">Videos de YouTube y Vimeo se pueden reproducir aquí. Un enlace externo conserva los permisos de su servicio.</span></label><label>Texto del ejercicio o código HTML (opcional)<textarea name="content" rows="5" maxlength="500000" placeholder="Escribe las instrucciones o pega un capítulo HTML autónomo.">${e(r.content||'')}</textarea></label><p class="field-hint">Usa una fuente por material: archivo, enlace o texto. Los capítulos HTML se muestran aislados del resto de la plataforma.</p></div>`,async fd=>{const data=values(fd),file=fd.get('file');delete data.file;if(fd.has('removeFile'))data.file=null;delete data.removeFile;data.position=Number(data.position);if(file?.size){if(file.size>20*1024*1024)throw new Error('El archivo supera el límite de 20 MB.');data.file={name:file.name,mime:file.type||'application/octet-stream',base64:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.readAsDataURL(file);})};}await(id?patch(`/admin/resources/${id}`,data):post(`/admin/modules/${moduleId}/resources`,data));await saved('Material guardado');},{wide:true});
}
function confirmAction(title,copy,fn) {openModal(title,`<p class="small-paragraph">${copy}</p>`,async()=>{await fn();await saved();},{submit:'Confirmar'});}
async function viewResource(id) {
 const r=findResource(id);if(!r)throw new Error('Abre primero el curso que contiene este recurso.');
 const initialUser=state.user?.id,initialRoute=route();
 if(student()){const opened=await post(`/progress/${id}/open`);if(state.user?.id!==initialUser||route()!==initialRoute)return;state.progress=state.progress.filter(p=>p.resourceId!==id).concat(opened);}
 const url=safeUrl(r.url),embed=videoEmbed(url),file=r.fileUrl;let view='';
 if(r.kind==='html'&&(r.content||file)){
  view=`<iframe title="${e(r.title)}" sandbox="allow-scripts" referrerpolicy="no-referrer" src="/api/resources/${encodeURIComponent(r.id)}/preview"></iframe>`;
 }else if(embed)view=`<iframe class="video" title="${e(r.title)}" src="${e(embed)}" allow="fullscreen; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;
 else if(file&&(r.fileMime==='application/pdf'||r.fileName?.toLowerCase().endsWith('.pdf')))view=`<iframe title="${e(r.title)}" src="${e(file)}"></iframe>`;
 else if(r.kind==='image'&&(file||url))view=`<img src="${e(file||url)}" alt="${e(r.title)}">`;
 else if(r.content)view=`<pre>${e(r.content)}</pre>`;
 else view=`<div class="empty"><div class="empty-icon">${icon(kindIcon(r.kind))}</div><h3>${e(r.title)}</h3><p>${file?'Descarga el archivo para abrirlo en tu dispositivo.':url?'Abre este material en su página original.':'Este material aún no tiene contenido.'}</p></div>`;
 const completed=state.progress.some(p=>p.resourceId===id&&p.completed);
 const completionLabel=completed?'Marcar pendiente':'Marcar completado';
 const actions=`${file?`<a class="btn secondary" href="${e(file)}" download aria-label="Descargar archivo" title="Descargar archivo">${icon('download')}<span class="viewer-action-label">Descargar</span></a>`:''}${url?`<a class="btn secondary" href="${e(url)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir enlace original" title="Abrir enlace original">${icon('link')}<span class="viewer-action-label">Abrir enlace</span></a>`:''}${state.user&&!admin()?`<button type="button" class="btn ${completed?'secondary':''}" data-action="complete:${id}" aria-label="${completionLabel}" title="${completionLabel}">${icon('check')}<span class="viewer-action-label">${completionLabel}</span></button>`:''}`;
 openResourceViewer(r,view,actions);
}
function importStudents() {
 openModal('Importar estudiantes',`<div class="form-stack"><p class="small-paragraph">Carga una lista CSV con las columnas <strong>cedula,nombre,correo</strong>. El correo es opcional. Conserva las cédulas como texto para no perder ceros.</p><label>Archivo CSV<input type="file" name="csv" accept=".csv,text/csv" required></label><p class="field-hint">Los estudiantes existentes no se duplican. Las matrículas se asignan después, desde Matrículas.</p>${btn('Descargar plantilla vacía','csv-template','secondary small','download')}</div>`,async fd=>{const f=fd.get('csv');if(f.size>1024*1024)throw new Error('La lista debe pesar menos de 1 MB.');const students=parseStudentsCsv(await f.text());if(!students.length)throw new Error('La lista no contiene estudiantes.');if(students.length>500)throw new Error('Importa hasta 500 estudiantes por lista.');const result=await post('/admin/students/bulk',{students});await saved('Lista procesada');state.importResult=result;openModal('Resultado de la importación',`<p class="small-paragraph">Se registraron ${result.created?.length||0} estudiantes. Guarda los códigos antes de cerrar.</p>${result.errors?.length?`<div class="notice warning" style="margin-top:15px">${result.errors.map(x=>e(x.error||x.message||JSON.stringify(x))).join('<br>')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>ESTUDIANTE</th><th>CÉDULA</th><th>CÓDIGO</th></tr></thead><tbody>${(result.created||[]).map(s=>`<tr><td>${e(s.name)}</td><td>${e(s.document)}</td><td><code>${e(s.activationCode)}</code></td></tr>`).join('')}</tbody></table></div><div class="form-actions">${btn('Guardar códigos','export-codes','secondary','download')}${btn('Listo','close-modal')}</div>`,null,{wide:true});},{submit:'Importar estudiantes'});
}
function downloadText(name,text,type='text/csv') {const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importMigration() {
 openModal('Importar el aula local',`<div class="form-stack"><p class="small-paragraph">El traslado incluye los cursos, estudiantes, matrículas, avances y materiales del archivo. Solo se permite cuando esta plataforma aún no tiene cursos ni estudiantes.</p><label>Archivo de migración<input type="file" name="bundle" accept=".json,application/json" required></label><p class="field-hint">La cuenta de administrador y su contraseña actuales se conservan. Las sesiones y los códigos de activación anteriores no se trasladan.</p></div>`,async fd=>{
  const file=fd.get('bundle');if(!file?.size)throw new Error('Selecciona el archivo de migración.');if(file.size>64*1024*1024)throw new Error('La copia supera el límite de 64 MB.');
  let bundle;try{bundle=JSON.parse(await file.text());}catch{throw new Error('El archivo no contiene una copia JSON válida.');}
  if(!bundle||bundle.format!=='aula-abierta-migration'||bundle.version!==1)throw new Error('El archivo no es una copia compatible de Aula Abierta.');
  const result=await post('/admin/migration',bundle);await saved('Traslado completado');
  const counts=result.imported;openModal('Tu aula ya está trasladada',`<p class="small-paragraph">Se importaron ${Number(counts.courses)} cursos, ${Number(counts.students)} estudiantes, ${Number(counts.resources)} recursos y ${Number(counts.enrollments)} matrículas.</p><p class="field-hint" style="margin-top:16px">Los estudiantes que aún no tengan contraseña necesitarán un código nuevo desde Estudiantes.</p><div class="form-actions">${btn('Continuar','close-modal')}</div>`);
 },{submit:'Importar en esta plataforma'});
}
function csvCell(text){let t=String(text??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"';}
function bindForms() {
 document.getElementById('login-form')?.addEventListener('submit',ev=>{ev.preventDefault();submitForm(ev.currentTarget,async fd=>{const result=await post(state.loginMode==='activate'?'/auth/activate':'/auth/login',values(fd));state.user=result.user;state.assurance=result.assurance;state.currentCourse=null;await refresh();location.hash=state.afterLoginCourse?'curso/'+state.afterLoginCourse:admin()?'inicio':'mis-cursos';state.afterLoginCourse=null;await render();toast('Bienvenido a tu aula');});});
 document.getElementById('settings-form')?.addEventListener('submit',ev=>{ev.preventDefault();submitForm(ev.currentTarget,async fd=>{state.settings=await patch('/admin/settings',values(fd));await render();toast('Configuración guardada');});});
}
modal.addEventListener('submit',ev=>{if(ev.target.id==='modal-form'){ev.preventDefault();submitForm(ev.target,fd=>modalHandler(fd));}});
modal.addEventListener('close',async()=>{
 if(modal.open)return;
 const resourceId=state.activeResourceId,originRoute=state.activeResourceRoute,scroll=window.scrollY,initialUser=state.user?.id;
 state.activeResourceId=null;state.activeResourceRoute=null;
 modal.replaceChildren();modalHandler=null;
 document.documentElement.classList.remove('resource-viewer-open');
 if(state.importResult)state.importResult=null;
 if(resourceId&&student()){
  try{const learning=await api('/learning');if(state.user?.id!==initialUser)return;state.learning=learning;}catch{/* The material's saved progress remains available. */}
  if(route()===originRoute&&!modal.open){await render();window.scrollTo(0,scroll);document.querySelector(`[data-action="resource:${resourceId}"]`)?.focus({preventScroll:true});}
  else if(route()==='mis-cursos'&&!modal.open&&student())await render();
 }
});

document.addEventListener('input',ev=>{if(ev.target.id==='search'){const position=ev.target.selectionStart;state.query=ev.target.value;render().then(()=>{const s=document.getElementById('search');s?.focus();s?.setSelectionRange(position,position);});}});
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;const [action,id]=el.dataset.action.split(':');
 try {
  switch(action){
   case 'menu':document.getElementById('sidebar').classList.toggle('open');break;
   case 'go':location.hash=id;break;
   case 'filter':state.filter=id;await render();break;
   case 'close-modal':modal.close();break;
   case 'resource-filter':state.resourceFilter=id;await render();break;
   case 'course-login':state.afterLoginCourse=id;state.loginMode=state.courses.find(c=>c.id===id)?.accessMode==='document'?'document':'password';location.hash='login';break;
   case 'study':{const [courseId,resourceId]=id.split('/');if(route()==='curso/'+courseId)await viewResource(resourceId);else{state.pendingResourceId=resourceId;location.hash='curso/'+courseId;}break;}
   case 'login-mode':state.loginMode=id;await render();break;
   case 'password-login':state.loginMode='password';state.afterLoginCourse=null;location.hash='login';break;
   case 'logout':await post('/auth/logout');state.user=null;state.assurance=null;state.currentCourse=null;await refresh();location.hash='catalogo';await render();break;
   case 'new-course':courseForm();break;
   case 'edit-course':courseForm(id);break;
   case 'publish-course':{const c=findCourse(id);await patch(`/admin/courses/${id}`,{published:!c.published});await saved(c.published?'Curso guardado como borrador':'Curso publicado');break;}
   case 'delete-course':confirmAction('Eliminar curso','Se eliminarán sus capítulos, materiales y matrículas. Esta acción no se puede deshacer.',async()=>{await api(`/admin/courses/${id}`,{method:'DELETE'});location.hash='cursos';});break;
   case 'new-student':studentForm();break;
   case 'edit-student':studentForm(id);break;
   case 'activate-student':openModal('Generar un código nuevo','<p class="small-paragraph">Se invalidarán las sesiones y cualquier código anterior de este estudiante. Entrégale el nuevo código de forma privada.</p>',async()=>{const s=state.students.find(x=>x.id===id);const result=await post(`/admin/students/${id}/activation`);await saved('Código generado');showCode(result.activationCode,s.name);},{submit:'Generar código'});break;
   case 'import-students':importStudents();break;
   case 'import-migration':importMigration();break;
   case 'csv-template':downloadText('plantilla-estudiantes.csv','\uFEFFcedula,nombre,correo\r\n');break;
   case 'export-codes':if(state.importResult)downloadText('codigos-estudiantes.csv','\uFEFFcedula,nombre,codigo\r\n'+state.importResult.created.map(s=>[s.document,s.name,s.activationCode].map(csvCell).join(',')).join('\r\n'));break;
   case 'new-enrollment':enrollmentForm();break;
   case 'enroll-course':enrollmentForm(null,id);break;
   case 'edit-enrollment':enrollmentForm(id);break;
   case 'toggle-enrollment':{const x=state.enrollments.find(y=>y.id===id);confirmAction(x.status==='active'?'Revocar matrícula':'Reactivar matrícula',x.status==='active'?'El estudiante perderá el acceso a este curso restringido.':'Se restaurará la matrícula con sus fechas actuales.',()=>patch(`/admin/enrollments/${id}`,{status:x.status==='active'?'revoked':'active'}));break;}
   case 'new-module':moduleForm(null,id);break;
   case 'edit-module':moduleForm(id);break;
   case 'delete-module':confirmAction('Eliminar capítulo','También se eliminarán los recursos de este capítulo.',()=>api(`/admin/modules/${id}`,{method:'DELETE'}));break;
   case 'new-resource':resourceForm(null,id);break;
   case 'edit-resource':resourceForm(id);break;
   case 'delete-resource':confirmAction('Eliminar material','Este material dejará de estar disponible para los estudiantes.',()=>api(`/admin/resources/${id}`,{method:'DELETE'}));break;
   case 'resource':await viewResource(id);break;
   case 'library-add':location.hash='cursos';toast('Abre un curso y añade materiales en sus capítulos');break;
   case 'complete':{const completed=!state.progress.some(x=>x.resourceId===id&&x.completed);const updated=await api(`/progress/${id}`,{method:'PUT',body:{completed}});state.progress=state.progress.filter(p=>p.resourceId!==id).concat(updated);modal.close();toast(completed?'Material completado':'Material marcado como pendiente');break;}
   case 'change-password':openModal('Cambiar contraseña','<div class="form-stack"><label>Contraseña actual<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nueva contraseña<input name="newPassword" type="password" autocomplete="new-password" minlength="12" required><span class="field-hint">Usa al menos 12 caracteres.</span></label></div>',async fd=>{await post('/auth/password',values(fd));await post('/auth/logout');state.user=null;state.assurance=null;modal.close();location.hash='login';await render();toast('Contraseña actualizada. Ingresa nuevamente.');});break;
   case 'help':openModal(admin()?'Tu aula, paso a paso':'Tu aprendizaje, paso a paso',`<div class="steps">${quickGuide(state.user?.role).map(([t,c],i)=>`<div class="step"><span class="step-number">${i+1}</span><div><strong>${e(t)}</strong><p>${e(c)}</p></div></div>`).join('')}</div><div class="form-actions">${btn('Entendido','close-modal')}</div>`);break;
   case 'reload':await boot();break;
  }
 }catch(err){toast(err.message);}
});
window.addEventListener('hashchange',()=>{if(modal.open&&modal.classList.contains('resource-viewer'))modal.close();state.query='';state.filter='all';state.resourceFilter='all';render();window.scrollTo(0,0);});
async function boot() {
 try { const [status,session,settings]=await Promise.all([api('/status'),api('/auth/me'),api('/settings')]);Object.assign(state,session,{settings,setupRequired:status.setupRequired});await refresh();await render(); }
 catch(error){app.innerHTML=publicShell(heading('No pudimos conectar con el aula','Intenta nuevamente en unos momentos. Si el problema continúa, comunícate con tu docente.')+btn('Volver a intentar','reload','secondary','arrow'));}
}
boot();





